class Solution {
public:
    int maxSubstringLength(string s) {
        int n = s.size();

        vector<int> first(26, -1);
        vector<int> last(26, -1);

        for (int i = 0; i < n; ++i) {
            int c = s[i] - 'a';

            if (first[c] == -1)
                first[c] = i;

            last[c] = i;
        }

        int ans = -1;

        // Every valid substring must begin at
        // the first occurrence of its first character.
        for (int c = 0; c < 26; ++c) {
            int start = first[c];

            if (start == -1)
                continue;

            int end = last[c];

            for (int j = start; j < n; ++j) {
                int ch = s[j] - 'a';

                // This character also occurs before start.
                // No longer substring starting here can work.
                if (first[ch] < start)
                    break;

                end = max(end, last[ch]);

                // All characters encountered so far
                // are contained within [start, j].
                if (j == end && j - start + 1 < n) {
                    ans = max(ans, j - start + 1);
                }
            }
        }

        return ans;
    }
};
